    {
        if (!disposedValue)
        {
            if (disposing)
            {
                _resource?.Dispose();
            }

            _resource = null;

            disposedValue = true;
        }
    }

    ~ExampleClass()
    {
       Dispose(disposing: false);
    }

    public void Dispose()
